+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+/**
+ * A request to open the Description secondary view.
+ *
+ * @typedef {object} CalendarEventDescriptionRequest
+ * @property {"description"} subview - The requested view.
+ */
+
+/**
+ * Requests Description navigation without reading or editing event data.
+ * Template ID: #calendarEventDescriptionRowTemplate
+ *
+ * @tagname calendar-event-description-row
+ * @fires requestsubview - A bubbling CustomEvent whose
+ *   CalendarEventDescriptionRequest detail identifies the requested view.
+ */
+class CalendarEventDescriptionRow extends HTMLElement {
+  connectedCallback() {
+    if (this.hasConnected) {
+      return;
+    }
+
+    this.hasConnected = true;
+    const template = document.getElementById(
+      "calendarEventDescriptionRowTemplate"
+    );
+
+    // Route replacements clone the labeled button to avoid an unnamed control
+    // while Fluent translates newly inserted nodes.
+    if (!this.firstElementChild) {
+      this.append(template.content.cloneNode(true));
+    }
+
+    this.querySelector("button").addEventListener("click", this);
+    window.MozXULElement?.insertFTLIfNeeded("messenger/calendarDialog.ftl");
+  }
+
+  handleEvent(event) {
+    if (event.type !== "click") {
+      return;
+    }
+
+    this.dispatchEvent(
+      new CustomEvent("requestsubview", {
+        bubbles: true,
+        detail: { subview: "description" },
+      })
+    );
+  }
+}
+
+customElements.define(
+  "calendar-event-description-row",
+  CalendarEventDescriptionRow
+);
