+/**
+ * Checks the names and roles exposed to screen readers by a native button.
+ *
+ * @param {HTMLButtonElement} button - The button to inspect.
+ * @param {string} name - The expected accessible name.
+ */
+async function assertAccessibleButton(button, name) {
+  const service = Cc["@mozilla.org/accessibilityService;1"].getService(
+    Ci.nsIAccessibilityService
+  );
+  let accessible;
+
+  await TestUtils.waitForCondition(() => {
+    accessible = service.getAccessibleFor(button);
+
+    return accessible?.name === name;
+  }, `The button should expose the name ${name}`);
+
+  Assert.equal(
+    accessible.name,
+    name,
+    "Screen readers should receive the button name."
+  );
+  Assert.equal(
+    accessible.role,
+    Ci.nsIAccessibleRole.ROLE_PUSHBUTTON,
+    "The entry should expose the native push-button role."
+  );
+}
