+    "",
+    "The entry should inherit Calendar spacing tokens."
+  );
+  Assert.equal(
+    row.querySelectorAll("img").length,
+    2,
+    "The row should render its icon and chevron."
+  );
+
+  for (const selector of [".icon-description", ".icon-nav-right"]) {
+    const icon = row.querySelector(selector);
+    Assert.ok(icon, "The row should contain the expected icon.");
+    Assert.equal(icon.alt, "", "The icon should be decorative.");
+    Assert.notEqual(
+      win.getComputedStyle(icon).content,
+      "none",
+      "The icon should have a themed image."
+    );
+  }
+
+  Assert.equal(
+    row.querySelector("input, textarea, [contenteditable], browser, iframe"),
+    null,
+    "The row should contain no editor, document browser, or value control."
+  );
+  Assert.equal(
+    typeof row.selectValue,
+    "undefined",
+    "The row should have no store-pulling getter."
+  );
