+add_task(async function test_routeReplacementAndClose() {
+  await openCreate();
+  const win = browser.contentWindow;
+  const doc = win.document;
+  const manager = dialog.querySelector("calendar-dialog-subview-manager");
+  const oldRow = dialog.querySelector("calendar-event-description-row");
+  const oldButton = oldRow.querySelector("button");
+  const oldBack = dialog.querySelector(".back-button");
+  const obsoleteRequest = new win.CustomEvent("requestsubview", {
+    bubbles: true,
+    detail: { subview: "description" },
+  });
+
+  oldButton.click();
+  dialog.setCalendarEventRoute();
+  Assert.ok(
+    manager.isDefaultSubviewVisible(),
+    "Replacement should immediately restore the main view."
+  );
+  Assert.equal(
+    manager.style.height,
+    "",
+    "Replacement should release the old size lock."
+  );
+  Assert.equal(
+    doc.activeElement,
+    dialog,
+    "Replacement should move focus out of the obsolete view."
+  );
+  Assert.ok(
+    await dialog.show(),
+    "The replacement create route should become ready."
+  );
+  await doc.l10n.translateFragment(dialog);
+
+  const row = dialog.querySelector("calendar-event-description-row");
+  const button = row.querySelector("button");
+  Assert.notEqual(row, oldRow, "A replacement route should get a new entry.");
+  row.after(oldRow);
+  oldButton.click();
+  oldRow.dispatchEvent(obsoleteRequest);
+  oldRow.remove();
+  dialog.dispatchEvent(obsoleteRequest);
+  Assert.ok(
+    manager.isDefaultSubviewVisible(),
+    "Obsolete entry requests should not navigate a replacement route."
+  );
+
+  button.click();
+  Assert.ok(
+    !manager.isDefaultSubviewVisible(),
+    "The new entry should navigate normally."
+  );
+  dialog.querySelector(".back-button").after(oldBack);
+  oldBack.click();
+  oldBack.remove();
+  Assert.ok(
+    !manager.isDefaultSubviewVisible(),
+    "An obsolete Back control should not change the new view."
+  );
+  dialog.querySelector(".back-button").click();
+  Assert.equal(
+    doc.activeElement,
+    button,
+    "Current Back should focus the current entry."
+  );
+
+  button.click();
+  dialog.close();
+  oldRow.dispatchEvent(obsoleteRequest);
+  Assert.ok(
+    manager.isDefaultSubviewVisible(),
+    "Close should reset navigation and ignore old requests."
+  );
+  Assert.ok(
+    await dialog.show(),
+    "The dialog should reopen with a fresh route."
+  );
+  Assert.ok(
+    manager.isDefaultSubviewVisible(),
+    "Reopening should start on the main view."
+  );
+  dialog.close();
+});
